// The ensemble's integer tables (src/ensemble_tables.cc, generated by gen_tables.py).

#ifndef COOP_ENSEMBLE_ENSEMBLE_TABLES_H_
#define COOP_ENSEMBLE_ENSEMBLE_TABLES_H_

#include <cstdint>

namespace coop_ensemble {

extern const uint32_t kRateTable[33];          // slow LFO increment per sample at rate i / 32
extern const int32_t kCapTable[33];            // the sweep's peak at depth 1, Q8 samples
extern const int16_t kSine[1025];              // Q15 sine, 1024 points + 1 guard
extern const uint32_t kEnsembleFastIncrement;  // 6.57 Hz

// 2 x SoftLimit over [0, 4] as int16 output samples, clipped (257 points), then the steps between them (256).
struct SoftLimitTable {
  int16_t value[257];
  int16_t step[256];
};
extern const SoftLimitTable kSoftLimit;

// Clouds' equal-power crossfade, Q31, 16 segments + 1 guard (te-op1-cfw ports/clouds/src/core/clouds_tables.cc).
extern const int32_t kXfadeInQ31[18];
extern const int32_t kXfadeOutQ31[18];

}  // namespace coop_ensemble

#endif  // COOP_ENSEMBLE_ENSEMBLE_TABLES_H_
